        "t_140": "🇸🇦 AR",
        "t_141": "<span>ANGEBOT ANFORDERN</span>",
        "t_142": "07. Angebot anfordern",
        "t_143": "> Der Broadcast-Barcelona-Knoten wird geladen...",
        "t_144": "IHR UNTERNEHMEN HAT GESCHICHTEN ZU ERZÄHLEN <br/> <span class=\"text-signal-red\">UND WIR LASSEN SIE KLINGEN</span>",
        "t_145": "<strong>CHUS BZN</strong> ist ein audiovisuelles Studio in Barcelona. Professioneller Ton und professionelles Bild, damit Ihr Unternehmen wie die Großen kommuniziert: Video, Musik, Streaming und KI-Inhalte, mit über 30 Jahren Erfahrung und der Nähe einer Werkstatt.",
        "t_146": "<span>ANGEBOT ANFORDERN</span>",
        "t_147": "<span>ARBEIT ANSEHEN</span>",
        "t_148": "Projekte nach Maß",
        "t_149": "BROADCAST",
        "t_150": "Professioneller Ton & Bild",
        "t_151": "24H",
        "t_152": "Antwort in &lt; 24h Werktagen · verfügbar 365 Tage",
        "t_153": "// TERMINALMATRIX-DATENSTREAM",
        "t_154": "ONLINE_60FPS",
        "t_155": "FIRMENVIDEO & DEMOS",
        "t_156": "SPOTS FÜR SOZIALE NETZWERKE",
        "t_157": "LIVE & STREAMING",
        "t_158": "PODCAST & VIDEOPODCAST",
        "t_159": "SOUND & MUSIK FÜR IHRE MARKE",
        "t_160": "INHALTE MIT KÜNSTLICHER INTELLIGENZ",
        "t_161": "AUDIOVISUELLES STUDIO IN BARCELONA",
        "t_162": "// UNSERE ARBEIT LIVE",
        "t_163": "Projekte & Reels",
        "t_164": "Video, Musik und Live-Formate für Marken jeder Größe. Sehen Sie selbst die echte Qualität der Arbeit, getragen von drei Jahrzehnten Erfahrung.",
        "t_165": "<div class=\"flex items-center justify-between\"><div class=\"p-3 bg-signal-red/20 text-signal-red rounded-lg group-hover:bg-signal-red group-hover:text-white transition-colors\"><svg class=\"w-8 h-8\" fill=\"currentColor\" viewbox=\"0 0 24 24\"><path d=\"M23.498 6.186a3.016 3.016 0 0 0-2.122-2.136C19.505 3.545 12 3.545 12 3.545s-7.505 0-9.377.505A3.017 3.017 0 0 0 .502 6.186C0 8.07 0 12 0 12s0 3.93.502 5.814a3.016 3.016 0 0 0 2.122 2.136c1.871.505 9.376.505 9.376.505s7.505 0 9.377-.505a3.015 3.015 0 0 0 2.122-2.136C24 15.93 24 12 24 12s0-3.93-.502-5.814zM9.545 15.568V8.432L15.818 12l-6.273 3.568z\"></path></svg></div><span class=\"font-mono text-[10px] text-signal-red uppercase font-bold\">VIDEOS ANSEHEN →</span></div><div><h3 class=\"font-headline text-2xl text-white uppercase group-hover:text-signal-red transition-colors\">Offizieller YouTube-Kanal</h3></div>",
