        "t_171": "<div class=\"flex items-center justify-between\"><div class=\"p-3 bg-signal-red/20 text-signal-red rounded-lg group-hover:bg-signal-red group-hover:text-white transition-colors\"><svg class=\"w-8 h-8\" fill=\"currentColor\" viewbox=\"0 0 24 24\"><path d=\"M12 0C5.37 0 0 5.37 0 12c0 5.31 3.435 9.795 8.205 11.385.6.105.825-.255.825-.57 0-.285-.015-1.23-.015-2.235-3.015.555-3.795-.735-4.035-1.41-.135-.345-.72-1.41-1.23-1.695-.42-.225-1.02-.78-.015-.795.945-.015 1.62.87 1.845 1.23 1.08 1.815 2.805 1.305 3.495.99.105-.78.42-1.305.765-1.605-2.67-.3-5.46-1.335-5.46-5.925 0-1.305.465-2.385 1.23-3.225-.12-.3-.54-1.53.12-3.18 0 0 1.005-.315 3.3 1.23.96-.27 1.98-.405 3-.405s2.04.135 3 .405c2.295-1.56 3.3-1.23 3.3-1.23.66 1.65.24 2.88.12 3.18.765.84 1.23 1.905 1.23 3.225 0 4.605-2.805 5.625-5.475 5.925.435.375.81 1.095.81 2.22 0 1.605-.015 2.895-.015 3.3 0 .315.225.69.825.57A12.02 12.02 0 0024 12c0-6.63-5.37-12-12-12z\"></path></svg></div><span class=\"font-mono text-[10px] text-signal-red uppercase font-bold\">監査コード →</span></div><div><h3 class=\"font-headline text-2xl text-white uppercase group-hover:text-signal-red transition-colors\">GitHub リポジトリ</h3></div>",
        "t_172": "// あなたのビジネスのためにできること",
        "t_173": "サービス＆オーダーメイド制作",
        "t_174": "サービスを選ぶと、明確な言葉で内容を確認できます。どのプロジェクトも唯一無二です。私たちもそう扱います。",
        "t_175": "// サービス 01",
        "t_176": "企業映像＆デモ",
        "t_177": "あなたの会社・商品・チームを、選ばれるためのクリアでプロフェッショナルな映像で紹介します。",
        "t_178": "内容を見る →",
        "t_179": "// サービス 02",
        "t_180": "SNS向けスポット",
        "t_181": "Instagram、TikTok、LinkedIn向けのフック付き縦型ショート。数秒で伝えるメッセージと行動喚起。",
        "t_182": "// サービス 03",
        "t_183": "ライブ＆ストリーミング",
        "t_184": "イベント、ローンチ、セミナー、カンファレンスを、放送品質のライブであらゆるチャンネルへ。",
        "t_185": "// サービス 04",
        "t_186": "ポッドキャスト＆ビデオポッドキャスト",
        "t_187": "あなたの番組を音声または映像で、オフィスでもスタジオでも。権威と親しみを生むコンテンツ。",
        "t_188": "// サービス 05",
        "t_189": "ブランドのためのサウンド＆ミュージック",
        "t_190": "音のアイデンティティ、ジングル、ナレーション、ミックス。大規模プロダクション級の品質（ライブセッション含む）。",
        "t_191": "// サービス 06",
        "t_192": "ポストプロダクション＆AIコンテンツ",
        "t_193": "1回の撮影から生まれるカラー・編集・コンテンツを、安全で合法的なAIで増幅。",
        "t_194": "// サービス 07",
        "t_195": "ビデオ研修",
        "t_196": "チームの学習と成長のためのコース、チュートリアル、オンボーディング動画。",
        "t_197": "// サービス 08",
        "t_198": "コミュニケーションのためのAI",
        "t_199": "あなたの会社にAIを導入：コンテンツ制作を倍増させるカタログ、広告、ワークフロー。",
        "t_200": "// 私たちのメソッド：職人技＋AI",
        "t_201": "結果の背後にあるメソッド",
        "t_202": "スタジオで開発した自社ツールで、より早く、安定した品質・管理されたコストでプロジェクトを完了させます。",
        "t_203": "v1.0.0 Stable // Electron + React",
        "t_204": "<strong>ローカルで完結するポストプロダクション：</strong>動画編集・画像処理・放送品質のマスタリングを1つのアプリに統合。",
        "t_205": "v1.0.0 Stable // FastAPI + FFmpeg",
        "t_206": "<strong>プロの色とフォーマットを即座に：</strong>シネマ用LUT、カラリメトリー、あらゆるプラットフォーム向け納品を最短時間で。",
        "t_207": "v1.0.0 Stable // LLM Multimodal",
