        "t_172": "// ماذا يمكننا أن نفعل لعملك",
        "t_173": "الخدمات والطلبات حسب الطلب",
        "t_174": "اختر خدمة وسترى ما تتضمنه، بلغة واضحة. كل مشروع فريد ونعامله على هذا الأساس.",
        "t_175": "// الخدمة 01",
        "t_176": "فيديو الشركات والعروض التوضيحية",
        "t_177": "نقدم شركتك أو منتجك أو فريقك في فيديو واضح واحترافي يجعلهم يختارونك.",
        "t_178": "شاهد ما تتضمنه ←",
        "t_179": "// الخدمة 02",
        "t_180": "إعلانات لشبكات التواصل",
        "t_181": "مقاطع رأسية قصيرة بمقدمة جذابة لإنستغرام وتيك توك ولينكد إن. رسالتك ودعوتك للفعل في ثوانٍ.",
        "t_182": "// الخدمة 03",
        "t_183": "البث المباشر والستريمينغ",
        "t_184": "فعاليات وإطلاقات وأيام مفتوحة ومؤتمرات بث مباشر بجودة البث التلفزيوني، على أي قناة.",
        "t_185": "// الخدمة 04",
        "t_186": "البودكاست وفيديو البودكاست",
        "t_187": "برنامجك صوتاً أو فيديو، في مكتبك أو في استوديواتنا. محتوى يصنع السلطة والقرب.",
        "t_188": "// الخدمة 05",
        "t_189": "صوت وموسيقى لعلامتك التجارية",
        "t_190": "هوية صوتية وجينغلز وتعليق صوتي ومكسات بجودة الإنتاجات الكبرى (تشمل الجلسات الحية).",
        "t_191": "// الخدمة 06",
        "t_192": "المونتاج والمحتوى بالذكاء الاصطناعي",
        "t_193": "ألوان ومونتاج ومقاطع تولد من تصوير واحد، معززة بذكاء اصطناعي آمن وقانوني.",
        "t_194": "// الخدمة 07",
        "t_195": "التدريب بالفيديو",
        "t_196": "دورات وبرامج تعليمية وفيديوهات تعريفية لينمو فريقك ويتعلم.",
        "t_197": "// الخدمة 08",
        "t_198": "الذكاء الاصطناعي لتواصلك",
        "t_199": "ننشر الذكاء الاصطناعي في شركتك: كتالوجات وإعلانات ومهام تضاعف إنتاجك من المحتوى.",
        "t_200": "// منهجنا: الاحتراف + الذكاء الاصطناعي",
        "t_201": "المنهج خلف النتيجة",
        "t_202": "أدوات خاصة، طورناها في استوديواتنا، لتُنفَّذ مشاريعك أسرع، بجودة ثابتة وتكلفة مضبوطة.",
        "t_203": "v1.0.0 Stable // Electron + React",
        "t_204": "<strong>مونتاجك محلياً:</strong> تطبيق واحد يجمع مونتاج الفيديو ومعالجة الصور والماستر بجودة البث الإذاعي.",
        "t_205": "v1.0.0 Stable // FastAPI + FFmpeg",
        "t_206": "<strong>ألوان وصيغ احترافية فوراً:</strong> LUT سينمائية، تصحيح الألوان وتسليم لأي منصة في وقت قياسي.",
        "t_207": "v1.0.0 Stable // LLM Multimodal",
