        "t_325": "[ SYS_LOG: BROADCAST_LINK_ESTABLISHED ]",
        "t_326": "<span class=\"font-headline text-3xl tracking-tight text-signal-red group-hover:scale-105 transition-transform\">CHUS BZN</span><span class=\"hidden sm:inline-block font-mono text-[10px] text-white/50 tracking-widest uppercase border-l border-white/20 pl-3\">الملف الشخصي والمهنة المدققة</span>",
        "t_327": "تدقيق الملاءة المهنية",
        "t_328": "CHUS BZN //<br/><span class=\"text-signal-red\">التدقيق والمسار الصناعي</span>",
        "t_329": "<strong>CHUS BZN</strong> تتمتع بتاريخ يمتد لأكثر من 33 عامًا في قيادة هندسة الأنظمة السمعية والبصرية وبث الصوت وتطوير الذكاء الاصطناعي لشبكات التلفزيون الرئيسية وشركات الإنتاج ومنصات البث العالمية.",
        "t_330": "أكثر من 33 عامًا من الملاءة المالية المدققة",
        "t_331": "FPCAT المستوى 3 الاعتماد الرسمي",
        "t_332": "شريك SGAE / AISGE / AEDYP / AIE",
        "t_333": "// برامج الملكية ودراسات الحالة",
        "t_334": "نظام بيئي معياري لسطح المكتب لتحرير الفيديو المتقدم ومعالجة الصور الضخمة ووحدة التحكم الرئيسية في DAW.",
        "t_335": "مسار سينمائي سريع للحقن الديناميكي لجداول البحث LUT الاحترافية (.cube)، وقياس الألوان في الوقت الفعلي، وتحويل الشفرة عالي الكفاءة.",
        "t_336": "محرك تنظيم الموسيقى بمساعدة الذكاء الاصطناعي لاستراتيجيات الهوية السليمة والتعليقات الصوتية العصبية وقوائم التشغيل التجارية.",
        "t_337": "نشر سير عمل هجين شامل حيث يعمل الذكاء الاصطناعي كمتجه تسريع في إنشاء بيئات مرئية ديناميكية، وتصميم الشخصيات المفاهيمية واستمرارية النص المحسنة للتوزيع الشامل.",
        "t_338": "دفق صوتي للطب الشرعي للتدريب والاستنساخ العصبي الشرعي للصوت من الأشرطة التناظرية والأساتذة التاريخيين. الامتثال الصارم لقانون الذكاء الاصطناعي للاتحاد الأوروبي والحماية مع AISGE.",
        "t_339": "// تاريخ المشاريع والإنتاج (1987 - الوقت الحاضر)",
        "t_340": "33 سنة من التاريخ الصناعي",
        "t_341": "Actuara12 (صاحب المختبر والاستوديو)",
        "t_342": "الريادة الفنية في فعاليات الشركات وإنتاج الأفلام وتطوير الحلول القائمة على الذكاء الاصطناعي.",
        "t_343": "هندسة الحلول والاستشارات التكنولوجية عالية المستوى للقطاع الإبداعي والشركات في برشلونة.",
        "t_344": "دبلجة وإنتاج ما بعد الأفلام الروائية (ثلاثية Lord of the Rings) والمسلسلات التلفزيونية (American Horror Story, CSI) لـ Netflix وHBO وSony Pictures.",
        "t_345": "التشغيل باستخدام التكنولوجيا التناظرية الصناعية: أنظمة 35 مم، ومسجلات الأشرطة المفتوحة متعددة المسارات ورمز الوقت التناظري.",
        "t_346": "// الإطار الأخلاقي والأمن القانوني",
        "t_347": "الامتثال وإدارة الحقوق",
        "t_348": "حماية حق المؤلف والمقطوعات الموسيقية.",
        "t_349": "حماية التفسيرات والسيادة البيومترية الصوتية.",
        "t_350": "رابطة دي جي ومنتجي الموسيقى الإلكترونية.",
        "t_351": "إدارة الملكية الفكرية للفنانين الأداء.",
        "t_352": "© 2026 CHUS BZN // المدرب المدقق والملاءة الفنية",
        "t_cta_quote": "اطلب 24 ساعة",
        "t_form_sub": "أرسل تفاصيل مشروعك. الرد مضمون خلال 24 ساعة عمل.",
        "t_form_title": "طلب عرض أسعار / استشارة",
        "t_hero_badge": "حالة_النظام: تشغيلي // شهادة FPCAT NVL3",
        "t_hero_btn_audit": "انظر مهنة التدقيق",
        "t_hero_btn_quote": "طلب عرض أسعار",
        "t_hero_sub": "الاندماج الاستراتيجي بين هندسة الصوت التناظرية وأحدث تقنيات الذكاء الاصطناعي. ثلاثة عقود من البنى التحتية الرائدة في مجال السينما والتلفزيون والبيئات الحضرية.",
        "t_meth_p1": "CHUS BZN هي وكالة سمعية بصرية رائدة وجماعية في برشلونة في إنشاء وتطوير المشاريع السمعية والبصرية والتكنولوجية المخصصة.",
        "t_meth_p2": "نحن متخصصون في إنشاء وتكامل وتطوير وأتمتة وتنفيذ الذكاء الاصطناعي في الشركات أو الشركات، ونعمل في ظل الامتثال الصارم للوائح الأوروبية (قانون الاتحاد الأوروبي للذكاء الاصطناعي).",
        "t_meth_title": "المنهجية الهجينة والجماعية العليا",
        "t_service_design_code": "// الملف 06 - الرسومات المتحركة والتصميم الجرافيكي",
        "t_service_design_desc": "إنشاء عناصر مرئية متحركة ثنائية وثلاثية الأبعاد، ومصدات للقنوات التلفزيونية، وحزم الاستمرارية الرسومية للبث المباشر وتصميم العلامات التجارية.",
        "t_service_design_specs": "<strong>الحلول التجارية والتسليمات:</strong><br/>• رسوم متحركة متقدمة في After Effects وBlender.<br/>• تكوين صوري ورسومي عالي الدقة.<br/>• <strong>تطبيق العميل:</strong> صورة الشركة والعروض الترويجية والرسومات عالية التأثير للأحداث.",
        "t_service_design_title": "الرسوم المتحركة والهوية البصرية",
        "t_service_dj_code": "// DOSSIER 04 - جلسات DJ والأداء المباشر والريمكسات",
        "t_service_dj_desc": "توجيه وتنفيذ جلسات الموسيقى المتقدمة للمهرجانات والأحداث الكلية للشركات والهوية السليمة للأماكن التجارية.",
        "t_service_dj_specs": "<strong>الحلول التجارية والتسليمات:</strong><br/>• التشغيل باستخدام الأجهزة الاحترافية الرائدة الرائدة (DDJ1000 / Rekordbox).<br/>• دراسة صوتية للغرفة وريمكسات استوديو حصرية تتكيف مع ملف تعريف الحدث.<br/>• <strong>تطبيق العميل:</strong> أحداث كبيرة الحجم واتفاقيات العلامة التجارية وإنتاج السجلات.",
